'use strict';

const user = {
  name: 'Ada',
  greet() { return 'hi ' + this.name; },
  later() { const f = () => 'hi ' + this.name; return f(); },
};
function check() { return this === undefined ? 'no-this' : 'has-this'; }
const greetAsGrace = user.greet.bind({ name: 'Grace' });

console.log(user.greet());
console.log(greetAsGrace());
console.log(user.later());
console.log(check());
console.log(String(user.greet === greetAsGrace));

