function myBind(fn, thisArg, ...preset) {
  return function (...args) {
    return fn.apply(thisArg, [...preset, ...args]);
  };
}

function add(a, b) { return this.base + a + b; }
const add10 = myBind(add, { base: 10 });
const add10and5 = myBind(add, { base: 10 }, 5);
console.log(add10(3, 4));
console.log(add10and5(4));
console.log(add10and5(4, 999));

