  constructor() {
    this.count = 0;
    this.inc = this.inc.bind(this);
  }
  inc() { this.count += 1; }
}

const c = new Counter();
const detached = c.inc; // callback boundary: receiver stays behind
detached();
detached();
console.log(c.count);

